const tabs=[['home','Home'],['card','Card'],['jobs','Jobs'],['class','Class'],['feed','Feed'],['settings','Settings']];
const adminTab=['admin','Admin'];
let active='home',stage=['signup','login','reset'].includes(location.hash.slice(1))?location.hash.slice(1):'splash',authenticated=false;
const app=document.querySelector('#app'),nav=document.querySelector('#nav'),toast=document.querySelector('#toast');
const appSheet=document.querySelector('#appSheet'),sheetBackdrop=document.querySelector('#sheetBackdrop'),sheetContent=document.querySelector('#sheetContent');
let savedState={};try{savedState=JSON.parse(localStorage.getItem('austonianState')||'{}')}catch{savedState={}}
const user={id:'',name:savedState.name||'Student',email:savedState.email||'',studentId:savedState.studentId||'',program:'',academicLevel:null,major:null,avatar:'',isAdmin:false,language:savedState.language||'English',appearance:savedState.appearance||'Light',notificationsEnabled:savedState.notificationsEnabled===true};
const SUPABASE_URL=window.__AUSTONIAN_CONFIG__?.supabaseUrl;
const SUPABASE_KEY=window.__AUSTONIAN_CONFIG__?.supabasePublishableKey;
if(!SUPABASE_URL||!SUPABASE_KEY)throw Error('Missing Austonian Hub configuration. Copy config.example.js to config.js and add your Supabase values.');
const supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const allowedEmail=email=>/^[^@\s]+@(st\.auston\.edu\.mm|auston\.edu\.mm)$/i.test(String(email).trim());
const claimOtpRequest=async email=>{const{data,error}=await supabaseClient.rpc('claim_otp_request',{p_email:email});if(error)throw error;const limit=Array.isArray(data)?data[0]:data;if(!limit?.allowed){const minutes=Math.max(1,Math.ceil(Number(limit?.retry_after_seconds||3600)/60));throw Error(`OTP request limit reached. Try again in ${minutes} minute${minutes===1?'':'s'}.`)}return limit};
const applyUser=profile=>{Object.assign(user,profile);persist()};
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let timetableItems=[];
let selectedScheduleDate=new Date(),scheduleDateTouched=false;
const loadTimetable=async()=>{const{data,error}=await supabaseClient.from('timetable').select('*').eq('published',true).order('starts_at');timetableItems=error?[]:data||[];if(!scheduleDateTouched&&timetableItems.length){const next=timetableItems.find(item=>new Date(item.ends_at)>new Date())||timetableItems[0];selectedScheduleDate=new Date(next.starts_at)}};
let contentItems=[];
const loadContent=async()=>{const{data,error}=await supabaseClient.from('content_items').select('*').eq('published',true).order('published_at',{ascending:false});contentItems=(error?[]:data||[]).map(item=>({...item,publishedAt:item.published_at,updatedAt:item.updated_at}))};
let adminStudents=[],academicAssignments=[],selectedAdminLevel='semester-2',selectedAdminMajor='CS';
const loadAdminStudents=async()=>{if(!user.isAdmin){adminStudents=[];return}const{data,error}=await supabaseClient.from('profiles').select('id,email,student_id,full_name,program,academic_level,major').order('full_name');adminStudents=error?[]:data||[]};
const loadAcademicAssignments=async()=>{if(!user.isAdmin){academicAssignments=[];return}const{data,error}=await supabaseClient.from('academic_assignments').select('email,academic_level,major,updated_at').order('academic_level').order('major').order('email');academicAssignments=error?[]:data||[]};
const loadProfile=async sessionUser=>{const{data,error}=await supabaseClient.from('profiles').select('id,email,student_id,full_name,program,academic_level,major,avatar_url,is_admin').eq('id',sessionUser.id).single();if(error)throw error;applyUser({id:data.id,email:data.email,studentId:data.student_id,name:data.full_name,program:data.program||'',academicLevel:data.academic_level||null,major:data.major||null,avatar:data.avatar_url||'',isAdmin:data.is_admin===true})};
const loadAppData=async()=>Promise.all([loadTimetable(),loadContent(),loadAdminStudents(),loadAcademicAssignments()]);
const visibleTabs=()=>user.isAdmin?[...tabs,adminTab]:tabs;
const contentBy=type=>contentItems.filter(item=>item.type===type);
const emptyState=(title,body,className='')=>`<section class="card empty-state ${esc(className)}"><strong>${esc(title)}</strong><p>${esc(body)}</p></section>`;
const persist=()=>{try{localStorage.setItem('austonianState',JSON.stringify(user))}catch{}}
const closeSheet=()=>{appSheet.classList.remove('open');setTimeout(()=>{appSheet.hidden=true;sheetBackdrop.hidden=true},280)};
const openSheet=(title,sub,content)=>{sheetContent.innerHTML=`<header class="sheet-head"><span class="eyebrow">AUSTONIAN HUB</span><h2>${title}</h2><p>${sub}</p></header>${content}`;appSheet.hidden=false;sheetBackdrop.hidden=false;requestAnimationFrame(()=>appSheet.classList.add('open'))};
const sheetFor=(action,source)=>{const text=source?.closest('.card,.figma-class-card')?.innerText||'';const sheets={
notify:['Notifications','Your latest published student updates',contentBy('notice').length||contentBy('deadline').length?`<div class="sheet-actions">${[...contentBy('notice'),...contentBy('deadline')].map(item=>`<button class="sheet-option"><span><strong>${esc(item.title)}</strong><small>${esc(item.body)}</small></span><b>›</b></button>`).join('')}</div>`:emptyState('No notifications','New notices and deadlines will appear here automatically.')],
details:['Class details','Published timetable information',`<div class="sheet-note">${text.replaceAll('\n','<br>')}</div>`],
profile:['Edit profile','Update your verified student identity',`<form class="sheet-form" data-sheet-form="profile"><label>FULL NAME<input name="name" required value="${esc(user.name)}"></label><label>VERIFIED EMAIL<input disabled value="${esc(user.email)}"></label><label>STUDENT PORTRAIT<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"></label><small>Maximum 1.8 MB</small><button class="primary wide">Save profile</button></form>`],
language:['Language','Choose your preferred app language',`<div class="sheet-actions"><button class="sheet-option" data-choice="language" data-value="English"><strong>English</strong><b>${user.language==='English'?'✓':''}</b></button><button class="sheet-option" data-choice="language" data-value="မြန်မာ"><strong>မြန်မာ</strong><b>${user.language==='မြန်မာ'?'✓':''}</b></button></div>`],
appearance:['Appearance','Choose how Austonian Hub looks',`<div class="sheet-actions"><button class="sheet-option" data-choice="appearance" data-value="Light"><strong>Light mode</strong><b>${user.appearance==='Light'?'✓':''}</b></button><button class="sheet-option" data-choice="appearance" data-value="Dark"><strong>Dark mode</strong><b>${user.appearance==='Dark'?'✓':''}</b></button></div>`],
privacy:['Privacy & security','Your authenticated account information',`<div class="sheet-actions"><div class="sheet-option"><span><strong>Verified email</strong><small>${esc(user.email)}</small></span><b>✓</b></div><div class="sheet-option"><span><strong>Current session</strong><small>This signed-in device</small></span><b>✓</b></div></div>`],
support:['Help & support','Official support details will be published here',emptyState('No support contacts published','Please use Auston’s official campus channels until support details are added.')],
schedule:['Add to My Schedule','Create a private timetable item',`<form id="personalTimetableForm" class="sheet-form management-form schedule-popup-form"><label>Title<input name="title" required placeholder="Study session"></label><label>Room or location<input name="room" placeholder="Library"></label><label>Lecturer or note<input name="lecturer" placeholder="Optional"></label><label class="schedule-date">Date<input name="scheduleDate" type="date" value="${calendarKey(selectedScheduleDate)}" required></label><div class="schedule-time-grid"><label>Start<input name="startTime" type="time" required></label><label>End<input name="endTime" type="time" required></label></div><button class="primary wide">Add to my timetable</button></form><p class="management-error" role="alert"></p>`]
};if(sheets[action])openSheet(...sheets[action])};
const showToast=(m)=>{toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)};
const header=(title,sub)=>`<header class="page-title"><h1>${title}</h1><p>${sub}</p></header>`;
const home=()=>{const next=timetableItems.find(item=>new Date(item.ends_at)>new Date()),deadlines=contentBy('deadline'),notices=contentBy('notice'),today=new Intl.DateTimeFormat(undefined,{weekday:'long',day:'numeric',month:'long'}).format(new Date());return `<div class="home-bg"><header class="header"><div><h1>Welcome, ${esc(user.name.split(' ')[0])}</h1><p>${esc(user.program||'Verified Auston student')}</p></div><button class="bell" data-action="notify" aria-label="Notifications">♧</button></header><section class="card summary"><span class="eyebrow">${esc(today.toUpperCase())}</span><h2>Your live overview</h2><div class="chips"><span class="chip">● &nbsp;${timetableItems.length} classes</span><span class="chip">● &nbsp;${deadlines.length} deadlines</span><span class="chip">● &nbsp;${notices.length} notices</span></div></section><h2 class="section-title">Classes</h2>${next?`<section class="card next"><span class="eyebrow">NEXT CLASS · ${esc(new Date(next.starts_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}</span><h2>${esc(next.title)}</h2><p>${esc([next.room,next.lecturer].filter(Boolean).join(' · '))}</p><button class="primary" data-tab="class">View class &nbsp;→</button></section>`:emptyState('No classes published','Your timetable will appear automatically when Auston publishes it.','next')}<h2 class="section-title">Due soon</h2>${deadlines.length?`<section class="card due-list">${deadlines.map(item=>`<div class="deadline"><div><strong>${esc(item.title)}</strong><small>${esc(item.body)}</small></div>${item.metadata?.label?`<span class="tag">${esc(item.metadata.label)}</span>`:''}</div>`).join('')}</section>`:emptyState('No deadlines','Published deadlines will appear here automatically.','due-list')}<h2 class="section-title">Notices</h2>${notices.length?`<section class="card notice-list">${notices.map(item=>`<article class="notice"><div class="notice-icon">!</div><div><strong>${esc(item.title)}</strong><p>${esc(item.body)}</p></div></article>`).join('')}</section>`:emptyState('No notices','Campus notices will appear here when published.','notice-list')}</div>`};
const card=()=>`${header('Student Card','Your verified digital campus identity')}<div class="id-card" id="idCard" tabindex="0" role="button" aria-label="Flip student ID"><div class="id-inner"><section class="id-face"><div class="id-brand"><img src="assets/auston-logo.png" alt="Auston"></div><div class="id-info"><div><h2>${esc(user.name)}</h2><p>Student ID &nbsp;: ${esc(user.studentId)}</p><p>${esc(user.email)}</p>${user.program?`<p>Program &nbsp;&nbsp;&nbsp;: ${esc(user.program)}</p>`:''}</div><div class="id-photo-wrap">${user.avatar?`<img class="portrait" src="${esc(user.avatar)}" alt="Student portrait">`:`<span class="portrait portrait-placeholder">${esc(user.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span>`}<button type="button" class="photo-edit" data-action="profile">Edit photo</button></div></div></section><section class="id-face id-back"><div class="qr" aria-hidden="true"></div><h2>Campus Access</h2><p>Live student pass</p><small>Tap to flip back</small></section></div></div><section class="card support"><h2>Your student identity</h2><p>Your name, student ID, email, and portrait are stored in your secured account.</p><div class="status-row"><span>Verification</span><b>ACTIVE</b></div></section>`;
const jobs=()=>{const items=contentBy('job');return `<div class="yellow-page">${header('Jobs & Internships','Opportunities published for Auston students')}<label class="search-box"><span>⌕</span><input aria-label="Search jobs" placeholder="Search published opportunities"></label><h2 class="section-title">Available opportunities</h2>${items.length?items.map(item=>`<article class="card job-card"><div class="job-logo">${esc(item.metadata?.initials||'JOB')}</div><div class="job-copy"><h3>${esc(item.title)}</h3><p>${esc([item.metadata?.company,item.metadata?.location].filter(Boolean).join(' · '))}</p>${item.body?`<small>${esc(item.body)}</small>`:''}</div><button class="save-btn" data-action="save" aria-label="Save ${esc(item.title)}">♡</button></article>`).join(''):emptyState('No jobs published','New jobs and internships will appear here automatically.')}</div>`};
const calendarKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const calendarMonthDays=date=>{const first=new Date(date.getFullYear(),date.getMonth(),1,12),count=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();return Array.from({length:count},(_,index)=>new Date(first.getFullYear(),first.getMonth(),index+1,12))};
const clockLabel=date=>date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
const freeTimeForDay=(items,date)=>{const start=new Date(date),end=new Date(date);start.setHours(8,0,0,0);end.setHours(20,0,0,0);const busy=items.map(item=>({start:new Date(Math.max(start,new Date(item.starts_at))),end:new Date(Math.min(end,new Date(item.ends_at)))})).filter(slot=>slot.end>slot.start).sort((a,b)=>a.start-b.start),merged=[];busy.forEach(slot=>{const last=merged.at(-1);if(last&&slot.start<=last.end)last.end=new Date(Math.max(last.end,slot.end));else merged.push(slot)});const free=[];let cursor=start;merged.forEach(slot=>{if(slot.start-cursor>=30*60000)free.push({start:new Date(cursor),end:new Date(slot.start)});if(slot.end>cursor)cursor=slot.end});if(end-cursor>=30*60000)free.push({start:new Date(cursor),end:new Date(end)});return free};
const scheduleCard=(item,index)=>{const start=new Date(item.starts_at),end=new Date(item.ends_at),personal=item.source==='personal'&&item.created_by===user.id,official=item.source!=='personal',canRemove=personal||(user.isAdmin&&official),progress=[76,49,18][index%3];return `<article class="figma-class-card ${personal?'is-personal':'is-official'}"><button class="figma-class-main" data-action="details"><time class="figma-class-time tone-${index%3}">${esc(clockLabel(start))}</time><span class="figma-class-copy"><span class="schedule-kind">${personal?'MY TIME':'OFFICIAL CLASS'}</span><strong>${esc(item.title)}</strong><small>${esc([item.room,item.lecturer].filter(Boolean).join(' · ')||'No location')}</small><i><b style="width:${progress}%"></b></i><em>${esc(clockLabel(start))}–${esc(clockLabel(end))}</em></span></button>${canRemove?`<button class="item-delete" data-delete-timetable="${item.id}" data-delete-kind="${official?'official':'personal'}" aria-label="${official?'Cancel official class':'Remove personal time'} ${esc(item.title)}">×</button>`:''}</article>`};
const classes=()=>{const days=calendarMonthDays(selectedScheduleDate),selectedKey=calendarKey(selectedScheduleDate),dayItems=timetableItems.filter(item=>calendarKey(new Date(item.starts_at))===selectedKey),freeSlots=freeTimeForDay(dayItems,selectedScheduleDate),deadline=contentBy('deadline')[0],dayLabel=selectedScheduleDate.toLocaleDateString([],{weekday:'long'}),monthLabel=selectedScheduleDate.toLocaleDateString([],{month:'long',year:'numeric'});return `<div class="figma-calendar-page"><header class="figma-calendar-header"><h1>Class Calendar</h1><p>Official classes and your private schedule in one view</p></header><div class="figma-calendar-layout"><section class="figma-calendar-controls"><div class="figma-month-selector"><button data-calendar-shift="-1" aria-label="Previous month">‹</button><strong>${esc(monthLabel)}</strong><button data-calendar-shift="1" aria-label="Next month">›</button></div><div class="figma-week-strip" aria-label="Dates in ${esc(monthLabel)}">${days.map(day=>`<button class="${calendarKey(day)===selectedKey?'selected':''}" data-calendar-day="${calendarKey(day)}"><small>${esc(day.toLocaleDateString([],{weekday:'short'}).toUpperCase())}</small><strong>${day.getDate()}</strong></button>`).join('')}</div><div class="figma-day-summary"><strong>${esc(dayLabel)} · ${dayItems.length} item${dayItems.length===1?'':'s'}${deadline?' · 1 deadline':''}</strong><button data-action="schedule" aria-label="Add personal time">+</button></div><section class="free-time-card"><header><span><small>AVAILABLE TIME</small><strong>${freeSlots.length?`${freeSlots.length} free slot${freeSlots.length===1?'':'s'}`:'Fully booked'}</strong></span><button data-action="schedule">Add my time</button></header><div class="free-time-slots">${freeSlots.length?freeSlots.map(slot=>`<span>${esc(clockLabel(slot.start))}–${esc(clockLabel(slot.end))}</span>`).join(''):'<small>No 30-minute gaps between 8:00 AM and 8:00 PM.</small>'}</div><p>Compared with official classes and your personal schedule.</p></section></section><section class="figma-selected-day"><h2>${calendarKey(new Date())===selectedKey?'Today’s schedule':`${esc(dayLabel)}’s schedule`}</h2><div class="figma-schedule-list">${dayItems.length?dayItems.map(scheduleCard).join(''):`<div class="figma-no-class"><strong>No classes or personal time</strong><small>Swipe the dates horizontally or add your own schedule.</small><button class="secondary" data-action="schedule">Add my time</button></div>`}</div>${deadline?`<article class="figma-assessment"><span>!</span><div><strong>${esc(deadline.title)}</strong><small>${esc(deadline.body||'Open the deadline for details')}</small></div></article>`:''}</section></div></div>`};
const feed=()=>{const items=[...contentBy('event'),...contentBy('news')].sort((a,b)=>String(b.publishedAt).localeCompare(String(a.publishedAt)));return `<div class="yellow-page">${header('News & Activities','Official campus updates and events')}<h2 class="section-title">Latest updates</h2>${items.length?items.map(item=>`<article class="card social-card"><header><span class="mini-avatar">${esc(item.metadata?.initials||'AU')}</span><span><strong>${esc(item.metadata?.source||'Auston')}</strong><small>${esc(item.publishedAt?new Date(item.publishedAt).toLocaleDateString():'')}</small></span></header><span class="match-pill">${esc(item.type.toUpperCase())}</span><h2>${esc(item.title)}</h2><p>${esc(item.body)}</p></article>`).join(''):emptyState('No updates published','Official news and activities will appear here automatically.')}</div>`};
const notificationsGranted=()=>('Notification'in window)&&Notification.permission==='granted';
const notificationStatus=()=>!('Notification'in window)?'Not supported on this device':Notification.permission==='denied'?'Blocked in device settings':user.notificationsEnabled&&notificationsGranted()?'Enabled for live updates':'Tap to enable live updates';
const settings=()=>`<div class="yellow-page">${header('Settings','Account, preferences, and support')}<section class="card profile-card">${user.avatar?`<img class="profile-avatar" src="${esc(user.avatar)}" alt="${esc(user.name)}">`:`<span class="profile-avatar">${esc(user.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span>`}<div><h2>${esc(user.name)}</h2><p>${esc(user.studentId)} · ${esc(user.email)}</p></div><button class="secondary" data-action="profile">Edit profile</button></section><h2 class="section-title">Preferences</h2><section class="card settings-card"><button class="setting-row" data-action="notifications"><span class="setting-icon">♧</span><span><strong>Notifications</strong><small>${esc(notificationStatus())}</small></span><span class="toggle ${user.notificationsEnabled&&notificationsGranted()?'':'off'}" role="switch" aria-checked="${user.notificationsEnabled&&notificationsGranted()}"></span></button><button class="setting-row" data-action="language"><span class="setting-icon">文</span><span><strong>Language</strong><small>English</small></span><b>›</b></button><button class="setting-row" data-action="appearance"><span class="setting-icon">◐</span><span><strong>Appearance</strong><small>Light mode</small></span><b>›</b></button></section><h2 class="section-title">Account & Privacy</h2><section class="card settings-card">${[['⌾','Privacy & security','Password and permissions','privacy'],['?','Help & support','FAQs and contact options','support']].map(x=>`<button class="setting-row" data-action="${x[3]}"><span class="setting-icon">${x[0]}</span><span><strong>${x[1]}</strong><small>${x[2]}</small></span><b>›</b></button>`).join('')}</section><button class="signout wide" data-action="logout">Sign out</button><p class="version">Austonian Hub</p></div>`;
const studentOptions=()=>`<option value="">All students</option>${adminStudents.map(student=>`<option value="${student.id}">${esc(student.full_name)} — ${esc(student.student_id)}</option>`).join('')}`;
const academicLevels=[['foundation','Foundation'],['semester-1','1st Semester'],['semester-2','2nd Semester'],['semester-3','3rd Semester'],['semester-4','4th Semester'],['bachelor','Bachelor']];
const academicMajors=[['CS','Computer Science'],['NW','Networking'],['ME','Mechanical Engineering'],['EE','Electrical Engineering']];
const academicLevelLabel=value=>value==='all'?'All levels':academicLevels.find(([id])=>id===value)?.[1]||'Not assigned';
const academicMajorLabel=value=>academicMajors.find(([id])=>id===value)?.[1]||'Major not assigned';
const normalizeAcademicLevel=value=>{const key=String(value||'').trim().toLowerCase().replace(/[._-]+/g,' ').replace(/\s+/g,' '),aliases={'foundation':'foundation','foundation course':'foundation','1st sem':'semester-1','1st semester':'semester-1','semester 1':'semester-1','sem 1':'semester-1','2nd sem':'semester-2','2nd semester':'semester-2','semester 2':'semester-2','sem 2':'semester-2','3rd sem':'semester-3','3rd semester':'semester-3','semester 3':'semester-3','sem 3':'semester-3','4th sem':'semester-4','4th semester':'semester-4','semester 4':'semester-4','sem 4':'semester-4','bachelor':'bachelor','bachelors':'bachelor','bachelor degree':'bachelor'};return aliases[key]||null};
const normalizeMajor=value=>{const key=String(value||'').trim().toUpperCase().replace(/[._-]+/g,' '),aliases={'CS':'CS','COMPUTER SCIENCE':'CS','NW':'NW','NETWORKING':'NW','ME':'ME','MECHANICAL ENGINEERING':'ME','EE':'EE','ELECTRICAL ENGINEERING':'EE'};return aliases[key]||null};
const parseAcademicEntries=value=>{const entries=[],errors=[];String(value||'').split(/\r?\n/).forEach((raw,index)=>{const line=raw.trim();if(!line)return;const parts=line.split('|').map(part=>part.trim()),email=parts[0].toLowerCase(),academicLevel=normalizeAcademicLevel(parts[1]),major=normalizeMajor(parts[2]);if(parts.length!==3||!allowedEmail(email)||!academicLevel||!major){errors.push(`Line ${index+1}: use email@st.auston.edu.mm | 2nd Sem | CS`);return}entries.push({email,academic_level:academicLevel,major})});if(errors.length)throw Error(errors.slice(0,3).join(' · '));if(!entries.length)throw Error('Paste at least one email, level, and major.');return [...new Map(entries.map(entry=>[entry.email,entry])).values()]};
const academicStudentList=(selected=selectedAdminLevel,major=selectedAdminMajor)=>adminStudents.map(student=>`<label class="student-choice"><input type="checkbox" name="studentIds" value="${student.id}" data-academic-level="${esc(student.academic_level||'')}" data-major="${esc(student.major||'')}" ${student.academic_level===selected&&student.major===major?'checked':''}><span><strong>${esc(student.full_name)}</strong><small>${esc(student.email)} · ${esc(academicLevelLabel(student.academic_level))} · ${esc(student.major||'No major')}</small></span><b>${esc(student.student_id)}</b></label>`).join('')||'<p>No registered students yet.</p>';
const academicAssignmentList=()=>academicLevels.map(([level,label])=>{const rows=academicAssignments.filter(item=>item.academic_level===level);if(!rows.length)return'';return `<section class="assignment-group"><h3>${esc(label)} <span>${rows.length}</span></h3>${rows.map(item=>`<label class="assignment-choice"><input type="checkbox" name="assignmentEmails" value="${esc(item.email)}"><span>${esc(item.email)}</span><b class="major-badge">${esc(item.major||'—')}</b><b>${adminStudents.some(student=>student.email.toLowerCase()===item.email.toLowerCase())?'REGISTERED':'PENDING'}</b></label>`).join('')}</section>`}).join('')||'<p class="empty-assignment">No email assignments saved yet.</p>';
const admin=()=>{if(!user.isAdmin)return emptyState('Administrator access required','This area is restricted.');const targeted=item=>item.target_user_id?adminStudents.find(student=>student.id===item.target_user_id):null,assignedCount=adminStudents.filter(student=>student.academic_level).length;return `<div class="admin-page">${header('Admin Dashboard','Publish live information for all students or a selected student')}<section class="admin-stats"><article><strong>${adminStudents.length}</strong><span>Students</span></article><article><strong>${assignedCount}</strong><span>Groups assigned</span></article><article><strong>${contentItems.length}</strong><span>Published posts</span></article></section><section class="card semester-panel"><div class="semester-head"><div><span class="eyebrow">ACADEMIC GROUPS</span><h2>Assign students by programme stage</h2><p>Choose Foundation, Semester 1–4, or Bachelor, then select multiple students or select everyone.</p></div><label class="select-all-choice"><input type="checkbox" data-select-all-semester><span>Select all students</span></label></div><form id="semesterAssignmentForm"><label class="academic-level-picker">Academic group<select name="academicLevel">${academicLevels.map(([id,label])=>`<option value="${id}" ${id===selectedAdminLevel?'selected':''}>${label}</option>`).join('')}</select></label><div class="student-choice-list">${academicStudentList()}</div><button class="primary wide">Save selected group</button></form><p class="management-error" role="alert"></p></section><div class="admin-grid"><section class="card admin-panel"><span class="eyebrow">TIMETABLE</span><h2>Publish a class</h2><form id="adminTimetableForm" class="management-form"><label>Student audience<select name="targetUserId">${studentOptions()}</select></label><label>Class title<input name="title" required placeholder="Programming Fundamentals"></label><label>Lecturer<input name="lecturer" placeholder="Lecturer name"></label><label>Room<input name="room" placeholder="Room 301"></label><label>Starts<input name="startsAt" type="datetime-local" required></label><label>Ends<input name="endsAt" type="datetime-local" required></label><button class="primary">Publish timetable</button></form><p class="management-error" role="alert"></p></section><section class="card admin-panel"><span class="eyebrow">CONTENT</span><h2>Publish an update</h2><form id="adminContentForm" class="management-form"><label>Student audience<select name="targetUserId">${studentOptions()}</select></label><label>Type<select name="type"><option value="notice">Notification</option><option value="deadline">Deadline</option><option value="job">Job posting</option><option value="news">News</option><option value="event">Event</option></select></label><label>Title<input name="title" required placeholder="Update title"></label><label class="form-wide">Details<textarea name="body" required placeholder="Write the information students need"></textarea></label><label>Company (jobs)<input name="company" placeholder="Optional"></label><label>Location<input name="location" placeholder="Optional"></label><button class="primary form-wide">Publish update</button></form><p class="management-error" role="alert"></p></section></div><section class="card admin-roster"><span class="eyebrow">STUDENT DIRECTORY</span><h2>Name + Student ID</h2><div class="student-list">${adminStudents.map(student=>`<div><span><strong>${esc(student.full_name)}</strong><small>${esc(student.email)}</small></span><b>${esc(student.student_id)}</b></div>`).join('')||'<p>No registered students yet.</p>'}</div></section><section class="card admin-published"><span class="eyebrow">RECENTLY PUBLISHED</span><h2>Manage posts and timetables</h2><div class="published-list">${timetableItems.filter(item=>item.source!=='personal').slice(0,8).map(item=>`<div><span><strong>${esc(item.title)}</strong><small>Timetable · ${esc(targeted(item)?.student_id||'All students')}</small></span><button data-delete-timetable="${item.id}">Delete</button></div>`).join('')}${contentItems.slice(0,10).map(item=>`<div><span><strong>${esc(item.title)}</strong><small>${esc(item.type)} · ${esc(targeted(item)?.student_id||'All students')}</small></span><button data-delete-content="${item.id}">Delete</button></div>`).join('')||'<p>No published content yet.</p>'}</div></section></div>`};
const academicBulkPanel=()=>`<section class="card semester-panel assignment-panel"><div class="semester-head"><div><span class="eyebrow">EMAIL LIST IMPORT</span><h2>Assign semesters by email</h2><p>Paste one student per line. Registered students move into the selected category immediately; pending emails are assigned automatically when they create an account.</p></div></div><form id="academicBatchForm" class="management-form"><label class="form-wide">Email and academic group<textarea name="entries" required placeholder="student1@st.auston.edu.mm | 2nd Sem&#10;student2@st.auston.edu.mm | Foundation"></textarea></label><small class="assignment-format">Accepted groups: Foundation, 1st Sem, 2nd Sem, 3rd Sem, 4th Sem, Bachelor.</small><button class="primary form-wide">Import email list</button></form><p class="management-error" role="alert"></p><div class="assignment-list-head"><div><strong>Saved semester lists</strong><small>${academicAssignments.length} email${academicAssignments.length===1?'':'s'} in the database</small></div><label class="select-all-choice"><input type="checkbox" data-select-all-assignments><span>Select all</span></label></div><form id="removeAssignmentsForm"><div class="assignment-list">${academicAssignmentList()}</div><button class="danger-action wide" ${academicAssignments.length?'':'disabled'}>Remove selected</button></form><p class="management-error" role="alert"></p></section>`;
const levelOptions=(includeAll=false)=>`${includeAll?'<option value="all">All levels</option>':''}${academicLevels.map(([id,label])=>`<option value="${id}" ${id===selectedAdminLevel?'selected':''}>${label}</option>`).join('')}`;
const majorOptions=(includeAll=false)=>`${includeAll?'<option value="">All majors</option>':''}${academicMajors.map(([id,label])=>`<option value="${id}" ${id===selectedAdminMajor?'selected':''}>${id} — ${label}</option>`).join('')}`;
const studentOptionsV2=()=>`<option value="">Use level + major audience</option>${adminStudents.map(student=>`<option value="${student.id}">${esc(student.full_name)} — ${esc(student.student_id)} · ${esc(student.academic_level?academicLevelLabel(student.academic_level):'Unassigned')} · ${esc(student.major||'No major')}</option>`).join('')}`;
const academicBulkPanelV2=()=>`<section class="card admin-module assignment-panel"><div class="admin-module-head"><div><span class="eyebrow">BULK ENROLMENT</span><h2>Import level + major</h2><p>Add registered or future students. Pending assignments apply automatically after account creation.</p></div><span class="admin-count">${academicAssignments.length} saved</span></div><form id="academicBatchForm" class="management-form"><label class="form-wide">Email | Level | Major<textarea name="entries" required placeholder="student1@st.auston.edu.mm | 2nd Sem | CS&#10;student2@st.auston.edu.mm | Foundation | NW"></textarea></label><small class="assignment-format">Majors: CS, NW, ME, EE. Levels: Foundation, 1st–4th Semester, Bachelor.</small><button class="primary form-wide">Import academic groups</button></form><p class="management-error" role="alert"></p><div class="assignment-list-head"><div><strong>Saved academic groups</strong><small>Registered and pending student assignments</small></div><label class="select-all-choice"><input type="checkbox" data-select-all-assignments><span>Select all</span></label></div><form id="removeAssignmentsForm"><div class="assignment-list">${academicAssignmentList()}</div><button class="danger-action wide" ${academicAssignments.length?'':'disabled'}>Remove selected assignments</button></form><p class="management-error" role="alert"></p></section>`;
const academicPromotionPanel=()=>{const sourceIndex=Math.max(0,academicLevels.findIndex(([id])=>id===selectedAdminLevel)),nextLevel=academicLevels[Math.min(sourceIndex+1,academicLevels.length-1)][0],levelChoices=selected=>academicLevels.map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${label}</option>`).join(''),majorChoices=selected=>academicMajors.map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${id} — ${label}</option>`).join('');return `<section class="card admin-module promotion-panel"><div class="admin-module-head"><div><span class="eyebrow">SEMESTER PROGRESSION</span><h2>Promote an entire group</h2><p>Move every student and pending email assignment together. Their old official timetable disappears and the destination group timetable becomes available immediately.</p></div><span class="admin-count">ONE CLICK</span></div><form id="academicPromotionForm" class="management-form promotion-form"><label>From level<select name="fromLevel">${levelChoices(selectedAdminLevel)}</select></label><label>From major<select name="fromMajor">${majorChoices(selectedAdminMajor)}</select></label><span class="promotion-arrow" aria-hidden="true">→</span><label>To level<select name="toLevel">${levelChoices(nextLevel)}</select></label><label>To major<select name="toMajor">${majorChoices(selectedAdminMajor)}</select></label><button class="primary form-wide">Promote entire group</button></form><p class="management-error" role="alert"></p></section>`};
const adminV2=()=>{if(!user.isAdmin)return emptyState('Administrator access required','This area is restricted.');const assignedCount=adminStudents.filter(student=>student.academic_level&&student.major).length,officialCount=timetableItems.filter(item=>item.source!=='personal').length,targeted=item=>item.target_user_id?adminStudents.find(student=>student.id===item.target_user_id):null;return `<div class="admin-page admin-v2"><section class="admin-hero"><div><span class="eyebrow">AUSTON CONTROL CENTRE</span><h1>Student operations</h1><p>Manage academic groups, class schedules, and campus communication from one live workspace.</p></div><div class="admin-hero-user"><small>Signed in as</small><strong>${esc(user.name)}</strong><span>Administrator</span></div></section><section class="admin-stats"><article><small>REGISTERED</small><strong>${adminStudents.length}</strong><span>students</span></article><article><small>FULLY ASSIGNED</small><strong>${assignedCount}</strong><span>level + major</span></article><article><small>LIVE CLASSES</small><strong>${officialCount}</strong><span>official entries</span></article><article><small>UPDATES</small><strong>${contentItems.length}</strong><span>published posts</span></article></section><section class="card admin-module academic-manager"><div class="admin-module-head"><div><span class="eyebrow">ACADEMIC GROUPS</span><h2>Assign Level and Major</h2><p>Select a level, choose CS, NW, ME, or EE, then assign multiple students together.</p></div><label class="select-all-choice"><input type="checkbox" data-select-all-semester><span>Select all visible</span></label></div><form id="semesterAssignmentForm"><div class="academic-filter-grid"><label class="academic-level-picker">Level<select name="academicLevel">${levelOptions()}</select></label><label class="academic-level-picker">Major<select name="major">${majorOptions()}</select></label></div><div class="student-choice-list">${academicStudentList()}</div><button class="primary wide">Save Level + Major</button></form><p class="management-error" role="alert"></p></section>${academicPromotionPanel()}${academicBulkPanelV2()}<div class="admin-grid admin-publish-grid"><section class="card admin-module admin-panel"><div class="admin-module-head"><div><span class="eyebrow">CLASS PUBLISHER</span><h2>Publish to an academic group</h2><p>Every class is assigned to exactly one semester and major—never to all students.</p></div></div><form id="adminTimetableForm" class="management-form"><label>Semester<select name="cohort" required>${levelOptions()}</select></label><label>Major<select name="targetMajor" required>${majorOptions()}</select></label><label>Class title<input name="title" required placeholder="Programming Fundamentals"></label><label>Lecturer<input name="lecturer" placeholder="Lecturer name"></label><label>Room<input name="room" placeholder="Room 301"></label><label>Starts<input name="startsAt" type="datetime-local" required></label><label>Ends<input name="endsAt" type="datetime-local" required></label><button class="primary form-wide">Publish to semester + major</button></form><p class="management-error" role="alert"></p></section><section class="card admin-module admin-panel"><div class="admin-module-head"><div><span class="eyebrow">COMMUNICATIONS</span><h2>Publish an update</h2><p>Send notices, deadlines, jobs, news, and events.</p></div></div><form id="adminContentForm" class="management-form"><label class="form-wide">Student audience<select name="targetUserId">${studentOptions()}</select></label><label>Type<select name="type"><option value="notice">Notification</option><option value="deadline">Deadline</option><option value="job">Job posting</option><option value="news">News</option><option value="event">Event</option></select></label><label>Title<input name="title" required placeholder="Update title"></label><label class="form-wide">Details<textarea name="body" required placeholder="Write the information students need"></textarea></label><label>Company (jobs)<input name="company" placeholder="Optional"></label><label>Location<input name="location" placeholder="Optional"></label><button class="primary form-wide">Publish update</button></form><p class="management-error" role="alert"></p></section></div><section class="card admin-module admin-roster"><div class="admin-module-head"><div><span class="eyebrow">STUDENT DIRECTORY</span><h2>Students and academic groups</h2></div><span class="admin-count">${adminStudents.length} total</span></div><div class="student-list">${adminStudents.map(student=>`<div><span><strong>${esc(student.full_name)}</strong><small>${esc(student.email)} · ${esc(student.student_id)}</small></span><span class="student-group-tags"><b>${esc(student.academic_level?academicLevelLabel(student.academic_level):'No level')}</b><b>${esc(student.major||'No major')}</b></span></div>`).join('')||'<p>No registered students yet.</p>'}</div></section><section class="card admin-module admin-published"><div class="admin-module-head"><div><span class="eyebrow">LIVE CONTENT</span><h2>Manage published items</h2></div></div><div class="published-list">${timetableItems.filter(item=>item.source!=='personal').slice(0,12).map(item=>`<div><span><strong>${esc(item.title)}</strong><small>Class · ${esc(targeted(item)?.student_id||[academicLevelLabel(item.cohort),item.target_major].filter(Boolean).join(' · ')||'All students')}</small></span><button data-delete-timetable="${item.id}" data-delete-kind="official">Cancel</button></div>`).join('')}${contentItems.slice(0,12).map(item=>`<div><span><strong>${esc(item.title)}</strong><small>${esc(item.type)} · ${esc(targeted(item)?.student_id||'All students')}</small></span><button data-delete-content="${item.id}">Delete</button></div>`).join('')||'<p>No published content yet.</p>'}</div></section></div>`};
const adminWorkspace=()=>adminV2();
const views={home,card,jobs,class:classes,feed,settings,admin:adminWorkspace};
const desktopTopbar=()=>`<header class="desktop-topbar"><div><span class="eyebrow">${user.isAdmin&&active==='admin'?'ADMINISTRATION':'STUDENT WORKSPACE'}</span><h1>${esc(visibleTabs().find(([id])=>id===active)?.[1]||'Austonian Hub')}</h1></div><div class="desktop-user"><span><strong>${esc(user.name)}</strong><small>${user.isAdmin?'Administrator':esc(user.studentId)}</small></span>${user.avatar?`<img src="${esc(user.avatar)}" alt="${esc(user.name)}">`:`<b>${esc(user.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</b>`}</div></header>`;
const splash=()=>`<section class="auth-page splash"><img src="assets/auston-logo.png" alt="Auston"><p>Student experience, connected.</p><button class="sr-only" data-stage-go="start">Continue</button></section>`;
const start=()=>`<section class="auth-page landing-page"><header class="landing-nav"><a href="#" class="landing-logo" aria-label="Austonian Hub home"><img src="assets/auston-logo.png" alt="Auston"></a><nav aria-label="Landing navigation"><a href="#landingFeatures">Platform</a><a href="#landingAccess">Student access</a><a href="https://www.auston.edu.mm/" target="_blank" rel="noreferrer">Auston website</a></nav><div class="landing-actions"><a class="landing-login" href="#login">Log in</a><a class="landing-signup" href="#signup">Create account <span>→</span></a></div></header><main class="landing-main"><div class="landing-copy"><span class="landing-eyebrow">THE OFFICIAL STUDENT HUB</span><h1>Campus life.<br><em>One place.</em></h1><p>A secure digital home for Auston students—bringing your identity, classes, opportunities and campus updates together.</p><div class="landing-cta" id="landingAccess"><a class="landing-signup" href="#signup">Get student access <span>→</span></a><a class="landing-text-link" href="#login">I already have an account</a></div><div class="landing-assurance"><span><b>✓</b> Official email verification</span><span><b>✓</b> Real-time campus updates</span></div></div><aside class="landing-showcase" aria-label="Austonian Hub features"><div class="showcase-top"><span>STUDENT WORKSPACE</span><b>LIVE</b></div><div class="showcase-welcome"><small>YOUR AUSTONIAN HUB</small><h2>Everything that matters,<br>ready when you are.</h2></div><div class="showcase-grid"><article><span class="showcase-icon">ID</span><div><small>IDENTITY</small><strong>Digital student card</strong></div></article><article><span class="showcase-icon">▦</span><div><small>ACADEMICS</small><strong>Class timetable</strong></div></article><article><span class="showcase-icon">↗</span><div><small>OPPORTUNITIES</small><strong>Student careers</strong></div></article><article><span class="showcase-icon">●</span><div><small>CAMPUS</small><strong>News & activities</strong></div></article></div></aside></main><footer class="landing-features" id="landingFeatures"><div><span>01</span><p><strong>One verified profile</strong><small>Your Auston identity follows you across the hub.</small></p></div><div><span>02</span><p><strong>Always current</strong><small>Published information updates automatically.</small></p></div><div><span>03</span><p><strong>Designed for students</strong><small>Fast on mobile and purpose-built for laptops.</small></p></div></footer></section>`;
const authBrand=(mode)=>`<aside class="auth-brand" aria-label="Austonian Hub introduction"><a class="auth-brand-logo" href="#" aria-label="Austonian Hub home"><img src="assets/auston-logo.png" alt="Auston"></a><div class="auth-brand-copy"><span class="auth-kicker">AUSTONIAN HUB</span><h1>${mode==='signup'?'Everything you need.<br>One student account.':mode==='reset'?'Secure recovery.<br>Back to your hub.':'Your campus,<br>ready when you are.'}</h1><p>${mode==='signup'?'Create your verified profile to access your digital ID, timetable and campus services.':mode==='reset'?'Verify your official Auston inbox and choose a new password for your student account.':'Pick up where you left off and stay connected to student life.'}</p></div><div class="auth-proof"><span><b>01</b><small>Verified access</small></span><span><b>24/7</b><small>Live student hub</small></span><span><b>AU</b><small>Students only</small></span></div></aside>`;
const authNav=(active)=>`<nav class="auth-mode" aria-label="Account access"><a class="${active==='login'?'active':''}" href="#login">Log in</a><a class="${active==='signup'?'active':''}" href="#signup">Create account</a></nav>`;
const signup=()=>`<section class="auth-page auth-form-page auth-signup">${authBrand('signup')}<main class="auth-workspace">${authNav('signup')}<form id="signupForm" class="auth-panel"><header class="auth-heading"><span class="auth-step">NEW STUDENT PROFILE</span><h2>Join Austonian Hub</h2><p>Use your official Auston details. We’ll email you a six-digit verification code.</p></header><div class="auth-section"><div class="auth-section-title"><b>1</b><span><strong>Your details</strong><small>Enter the information on your student record</small></span></div><div class="auth-grid"><label class="field"><span>Full name</span><input name="name" autocomplete="name" placeholder="Your full name" required></label><label class="field"><span>Student ID</span><input name="studentId" placeholder="AU2501616" pattern="AU[0-9]{7}" autocomplete="off" required></label></div><label class="field"><span>Auston email address</span><input name="email" type="email" placeholder="you@st.auston.edu.mm" autocomplete="email" required></label><label class="field"><span>Create password</span><span class="password-wrap"><input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="At least 8 characters" required><button class="eye" type="button" data-eye aria-label="Show password">Show</button></span></label></div><div class="auth-section verification-section"><div class="auth-section-title"><b>2</b><span><strong>Verify your email</strong><small>Codes expire for your protection</small></span></div><button type="button" class="otp-send" data-send-otp>Send verification code <span>→</span></button><label class="field otp-field"><span>Six-digit code</span><input name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" autocomplete="one-time-code" required></label></div><label class="consent"><input name="consent" type="checkbox" required><span>I agree to the Privacy Policy and Terms of Use.</span></label><p class="form-error" id="signupError" role="alert"></p><button class="form-submit">Verify and create account <span>→</span></button><p class="auth-domain-note"><span>●</span> Restricted to @st.auston.edu.mm and @auston.edu.mm</p></form></main></section>`;
const login=()=>`<section class="auth-page auth-form-page auth-login">${authBrand('login')}<main class="auth-workspace">${authNav('login')}<form id="loginForm" class="auth-panel login-panel"><header class="auth-heading"><span class="auth-step">STUDENT SIGN IN</span><h2>Welcome back</h2><p>Enter your Auston email and password to open your workspace.</p></header><div class="login-fields"><label class="field"><span>Auston email address</span><input name="email" type="email" placeholder="you@st.auston.edu.mm" autocomplete="email" required></label><label class="field"><span>Password</span><span class="password-wrap"><input name="password" type="password" autocomplete="current-password" placeholder="Your password" required><button class="eye" type="button" data-eye aria-label="Show password">Show</button></span></label></div><div class="login-options"><label><input type="checkbox"> Keep me signed in</label><button type="button" class="auth-link" data-action="forgot">Forgot password?</button></div><p class="form-error" id="loginError" role="alert"></p><button class="form-submit">Open my student hub <span>→</span></button><div class="auth-security"><span>✓</span><p><strong>Secure student access</strong><small>Only official Auston email accounts can continue.</small></p></div></form></main></section>`;
const passwordReset=()=>`<section class="auth-page auth-form-page auth-reset">${authBrand('reset')}<main class="auth-workspace"><nav class="auth-mode reset-mode" aria-label="Password recovery"><a href="#login">← Back to login</a><span>Secure recovery</span></nav><form id="resetForm" class="auth-panel reset-panel"><header class="auth-heading"><span class="auth-step">PASSWORD RECOVERY</span><h2>Reset your password</h2><p>We’ll send a six-digit recovery code to your official Auston email.</p></header><div class="auth-section"><div class="auth-section-title"><b>1</b><span><strong>Verify your email</strong><small>Only registered Auston accounts can continue</small></span></div><label class="field"><span>Auston email address</span><input name="email" type="email" placeholder="you@st.auston.edu.mm" autocomplete="email" required></label><button type="button" class="otp-send" data-send-reset-otp>Send recovery code <span>→</span></button></div><div class="auth-section"><div class="auth-section-title"><b>2</b><span><strong>Choose a new password</strong><small>Enter the code from your Auston inbox</small></span></div><label class="field otp-field"><span>Six-digit recovery code</span><input name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" autocomplete="one-time-code" required></label><label class="field"><span>New password</span><span class="password-wrap"><input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="At least 8 characters" required><button class="eye" type="button" data-eye aria-label="Show password">Show</button></span></label><label class="field"><span>Confirm new password</span><span class="password-wrap"><input name="confirmPassword" type="password" minlength="8" autocomplete="new-password" placeholder="Repeat your new password" required><button class="eye" type="button" data-eye aria-label="Show password">Show</button></span></label></div><p class="form-error" id="resetError" role="alert"></p><button class="form-submit">Update password <span>→</span></button><p class="auth-domain-note"><span>●</span> Recovery codes are sent only to official Auston emails</p></form></main></section>`;
const stageViews={splash,start,signup,login,reset:passwordReset};
const isMobileViewport=()=>matchMedia('(max-width:599px)').matches;
if(isMobileViewport()&&navigator.maxTouchPoints>0){['gesturestart','gesturechange','gestureend'].forEach(type=>document.addEventListener(type,event=>event.preventDefault(),{passive:false}))}
let adTimer;
